import{_ as e,a as l,c as a,ac as r}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"排球规则 · 常见犯规与判例至官方资料与阅读范围","description":"以 FIVB 2025—2028 室内六人制规则理解排球计分、轮转、攻防、自由人与常见犯规","frontmatter":{"title":"排球规则 · 常见犯规与判例至官方资料与阅读范围","description":"以 FIVB 2025—2028 室内六人制规则理解排球计分、轮转、攻防、自由人与常见犯规","splitFrom":"life/personal/sports/volleyball-rules.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"排球规则","summary":"以 FIVB 2025—2028 室内六人制规则理解排球计分、轮转、攻防、自由人与常见犯规","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"排球规则 · 人数、场地与器材至自由人：能替后排，但有专门限制","link":"/life/personal/sports/volleyball-rules-part-01"},"next":{"text":"足球规则","link":"/life/personal/sports/football-rules"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"排球规则 · 人数、场地与器材至自由人：能替后排，但有专门限制","link":"/life/personal/sports/volleyball-rules-part-01"},"next":{"text":"足球规则","link":"/life/personal/sports/football-rules"}},"headers":[],"relativePath":"life/personal/sports/volleyball-rules-part-02.md","filePath":"life/personal/sports/volleyball-rules-part-02.md"}'),o={name:"life/personal/sports/volleyball-rules-part-02.md"};function i(d,t,n,s,p,h){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="排球规则-·-常见犯规与判例至官方资料与阅读范围" tabindex="-1">排球规则 · 常见犯规与判例至官方资料与阅读范围 <a class="header-anchor" href="#排球规则-·-常见犯规与判例至官方资料与阅读范围" aria-label="Permalink to &quot;排球规则 · 常见犯规与判例至官方资料与阅读范围&quot;">​</a></h1><p><a href="/life/personal/sports/volleyball-rules">返回分篇目录</a></p><p>排球由两队隔网对抗，目标是让球落在对方场内，或使对方无法合法回球。<strong>每个回合都有一方得分；接发球队赢得回合，还会获得发球权并顺时针轮转一位。</strong></p><p>本文采用 FIVB《Official Volleyball Rules 2025–2028》，适用于室内六人制，自 2025 年 1 月 1 日之后开始的比赛实施。沙滩排球、气排球、校园简化比赛和个别赛事试行条款，不直接套用本文。</p><h2 id="常见犯规与判例" tabindex="-1">常见犯规与判例 <a class="header-anchor" href="#常见犯规与判例" aria-label="Permalink to &quot;常见犯规与判例 {#常见犯规与判例}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>判断</th></tr></thead><tbody><tr><td>球一部分压到边线</td><td>界内，边界线属于场地</td></tr><tr><td>球碰网后正常落入对方场区</td><td>通常有效；发球触网也一样</td></tr><tr><td>扣球队员击球、起跳或落地动作中触及两标志杆之间的球网</td><td>属于触网犯规；不能概括成所有部位、任何时刻碰网都犯规</td></tr><tr><td>球把球网撞向队员</td><td>不因此判该队员触网犯规</td></tr><tr><td>脚越过中线，但部分脚仍接触或位于中线上方</td><td>在不干扰对方的条件下可以合法；整只脚越线落入对方场地则犯规</td></tr><tr><td>后排队员在进攻线后起跳扣球，落到前区</td><td>起跳位置与触球条件合法即可，落点不决定后排进攻犯规</td></tr><tr><td>拦网碰球后，本队再垫、传、扣</td><td>共 3 次队内击球，合法；拦网触球另计</td></tr><tr><td>自由人前区上手传球，队友跳起扣高于网顶的球</td><td>队友完成进攻性击球时犯规</td></tr></tbody></table><p>“打手出界”要判断最后触球：进攻球被合法拦网碰到后落在界外，通常由进攻方得分。若先触标志杆、触网犯规或进攻已犯规，则应按实际先后处理。</p><h2 id="用三个回合把身份、触球和比分连起来" tabindex="-1">用三个回合把身份、触球和比分连起来 <a class="header-anchor" href="#用三个回合把身份、触球和比分连起来" aria-label="Permalink to &quot;用三个回合把身份、触球和比分连起来 {#用三个回合把身份、触球和比分连起来}&quot;">​</a></h2><ol><li><strong>甲队接发，23∶24 落后。</strong> 乙队发球失误，甲得分为 24∶24，并顺时针轮转；原 2 号位到 1 号位发球。甲再得一分为 25∶24，仍未赢局，也不再轮转；再得一分到 26∶24 才赢。不能把“得分”和“轮转”绑在一起记。</li><li><strong>拦网后连续救球。</strong> 甲队前排拦网触球，球落回甲方，拦网者自己垫起，队友二传，再由另一人扣过网。拦网触球另计，垫、传、扣是本队三次击球，合法。若扣球前再多垫一次，则是四次击球。</li><li><strong>后排队员踩进攻线起跳。</strong> 他把整体高于网顶的球扣过网，属于后排进攻犯规，对方得分。若起跳时在进攻线后且未踩线，同样击球后落进前区，可以合法；决定条件是起跳位置和触球时球的高度，不是落地位置。</li></ol><h2 id="配合入门-接、传、攻各在解决什么" tabindex="-1">配合入门：接、传、攻各在解决什么 <a class="header-anchor" href="#配合入门-接、传、攻各在解决什么" aria-label="Permalink to &quot;配合入门：接、传、攻各在解决什么 {#配合入门-接、传、攻各在解决什么}&quot;">​</a></h2><p>接发球尽量把球送到可组织的位置，二传选择分给哪一路，攻手再尝试让球落地或造成打手出界；对方则通过拦网和后排防守把球救起。<strong>“一传、二传、进攻”是常见组织顺序，不是必须三次才准过网</strong>。接发不稳时直接把球合法送回，也可以继续比赛。</p><table tabindex="0"><thead><tr><th>术语或角色</th><th>看球时找什么</th></tr></thead><tbody><tr><td>一传</td><td>本队接对方发球的第一下；不是固定由一号位完成</td></tr><tr><td>二传</td><td>组织进攻的角色，也可指第二次组织触球；两者要结合语境</td></tr><tr><td>主攻、接应</td><td>常承担不同区域的进攻任务，轮到后排仍受后排限制</td></tr><tr><td>副攻</td><td>常在网前参与快攻和拦网，轮到后排可按规则被自由人替换</td></tr><tr><td>自由人</td><td>接发和防守的专门角色，不能因此获得前排进攻或拦网资格</td></tr><tr><td>失误送分</td><td>发球出界、四次击球等都可结束回合；不只有扣球落地才得分</td></tr><tr><td>打手出界</td><td>球经对方拦网触及后出界，关键是最后触球与此前是否已犯规</td></tr></tbody></table><p>如果只想先看懂一次回合，按“谁发球 → 谁接第一下 → 谁组织 → 谁完成进攻 → 谁最后触球”追踪，再去学复杂阵型。位置名称和战术选择不会改变触网、持球、后排进攻等基本限制。</p><h2 id="自测-理解一次回合" tabindex="-1">自测：理解一次回合 <a class="header-anchor" href="#自测-理解一次回合" aria-label="Permalink to &quot;自测：理解一次回合 {#自测-理解一次回合}&quot;">​</a></h2><ol><li>接发球队赢一分后，原 2 号位队员下一步做什么？</li><li>24∶24 后，一方先到 25 分，是否马上赢局？</li><li>发球擦网后落在对方场内，是否重发？</li><li>拦网触球后，拦网者自己再垫一次，是否合法？</li><li>发球队的后排队员能否因为站位自由，就在网前完成拦网？</li><li>自由人在前区垫球，队友完成高于网顶的扣球，是否仅因此犯规？</li></ol><p><strong>答案：</strong> 1. 顺时针轮转至 1 号位发球。2. 不能，须领先 2 分。3. 不重发，合法过网则继续。4. 可以，该垫球是本队第一次击球。5. 不能，后排身份不变。6. 不会，特定限制针对自由人在前区的上手手指传球，仍需检查其他进攻条件。</p><h2 id="官方资料与阅读范围" tabindex="-1">官方资料与阅读范围 <a class="header-anchor" href="#官方资料与阅读范围" aria-label="Permalink to &quot;官方资料与阅读范围 {#官方资料与阅读范围}&quot;">​</a></h2><p>资料核对日期：2026 年 10 月 23 日。已读取官方英文规则，重点核对第 6—7 条计分、轮转和站位，第 9—14 条击球、发球、进攻及拦网，以及第 19 条自由人规则。</p><ul><li><a href="https://www.fivb.com/volleyball/the-game/official-volleyball-rules/" target="_blank" rel="noopener noreferrer">FIVB 官方排球规则入口</a></li><li><a href="https://www.fivb.com/wp-content/uploads/2025/01/FIVB-Volleyball_Rules2025_2028-EN-v05.pdf" target="_blank" rel="noopener noreferrer">Official Volleyball Rules 2025–2028 英文版</a></li></ul><p>本文适合入门和日常观赛。正式执裁还需结合裁判指南、案例集与具体赛事规定，尤其注意临时试行规则和视频挑战程序。</p>',20)])])}const f=e(o,[["render",i]]);export{u as __pageData,f as default};
